/* global window, document, Blob, URL, setTimeout, esc, state, inspectionContext, templateHtml, toast, render, $ */
// Bounded synthetic Markdown filling scenario. No free-text interpretation.
const fillReply='数量：120 件；需求日期：2026-09-25。';
const fillInput='演示资料 S-01：申请日期 2026-09-10；申请单号 DEMO-CG-001；计划周期为临时；申请人林顾问；申请部门生产部；物料名称包装盒；规格型号 BX-01；物料编码 DEMO-BX-01；用途为生产物料；库存为 0 件，需要采购；建议供方示例包装公司，供方编号 DEMO-S-01；质量要求按演示包装规格说明核对。采购数量和需求日期未提供。研发样品区不适用于本次生产物料申请，保留原结构和签批空白。';
function fillSnapshot(x){return x.fillVersions?.[x.rev]||{}}
function fillMissing(x){const v=fillSnapshot(x);return ['quantity','date'].filter(k=>!v[k])}
function fillContent(x){let md=window.procurementFixtures.application.content;const v=fillSnapshot(x);const rows=[
 ['| 申请日期 |','| 申请日期 | 2026-09-10 | 申请单号 | DEMO-CG-001 |'],
 ['| 计划周期 |','| 计划周期 | □月度 □季度 □年度 ☑临时 | 申请人 | 林顾问（演示） |'],
 ['| 申请部门 |','| 申请部门 | ☑生产部 □研发部 | | |'],
 ['| 物料名称 |','| 物料名称 | 包装盒（演示） | 规格型号 | BX-01 |'],
 ['| 物料编码 |',`| 物料编码 | DEMO-BX-01 | 数量 | ${v.quantity||'【待补充：采购数量】'} |`],
 ['| 用途 |',`| 用途 | ☑生产物料 □研发样品 | 需求日期 | ${v.date||'【待补充：需求日期】'} |`],
 ['| 库存确认 |','| 库存确认 | □有库存 ☑需采购 | 库存量 | 0 件 |'],
 ['| 建议供方 |','| 建议供方 | 示例包装公司 | 供方编号 | DEMO-S-01 |'],
 ['| 质量要求 |','| 质量要求 | 按演示包装规格说明核对 | | |']];
 for(const [prefix,value] of rows){const lines=md.split('\n'),i=lines.findIndex(l=>l.startsWith(prefix));if(i>=0)lines[i]=value;md=lines.join('\n')}
 return md.replace('\n\n**版本**','\n\n> 填写演示：所有业务值为合成数据，不代表客户已执行采购或签批。\n\n**版本**').replace('**研发样品补充信息**（研发样品适用）：','**研发样品补充信息**（本次演示为生产物料，此区不适用；保留原结构）：');
}
function fillChanges(x){return x.rev===2?[{title:'申请信息与物料',fields:['申请日期','申请单号','计划周期','申请人','申请部门','物料名称','规格型号','物料编码']},{title:'用途、库存与供方',fields:['用途','库存确认','库存量','建议供方','供方编号','质量要求']},{title:'待补充的采购信息',fields:['数量','需求日期']}]:[{title:fillMissing(x).length?'本轮尚未补齐数据':'补齐数量与需求日期',fields:['数量','需求日期']}];}
function fillValue(md,key){for(const line of md.split('\n').filter(l=>l.startsWith('|'))){const cells=line.slice(1,-1).split('|').map(s=>s.trim());const i=cells.indexOf(key);if(i>=0&&i+1<cells.length)return cells[i+1]}return ''}
function fillChangesBody(x){const items=fillChanges(x),n=Math.min(x.changePositions?.[x.rev]||0,items.length-1),c=items[n];const before=x.rev===2?window.procurementFixtures.application.content:fillContent({...x,rev:x.rev-1});const after=fillContent(x);return `<div class="change-toolbar"><strong>${x.rev===2?'空白模板 → 填写候选':`候选 ${x.rev-1} → ${x.rev}`}</strong><div class="row"><button data-change-step="-1" ${n===0?'disabled':''}>↑ 上一处</button><span role="status">${n+1} / ${items.length}</span><button data-change-step="1" ${n===items.length-1?'disabled':''}>下一处 ↓</button></div></div><p class="small muted">合成填写演示 · 绿色为填入值，橙色为尚缺信息。签字保持空白。</p><section id="change-${n}" class="change-block" tabindex="-1"><div class="change-heading"><h3>${esc(c.title)}</h3><button data-quote="${esc(c.title)}">补充或纠正此处</button></div><div class="tablewrap context-table" tabindex="0" role="region" aria-label="填写字段变化"><table><thead><tr><th>模板字段</th><th>修改前</th><th>当前候选</th></tr></thead><tbody>${c.fields.map(key=>{const a=fillValue(before,key),b=fillValue(after,key);return `<tr><th>${key}</th><td>${esc(a||'空白')}</td><td>${b.includes('待补充')?`<span class="tag amber">${esc(b)}</span>`:a!==b?`<ins>${esc(b)}</ins>`:esc(b)}</td></tr>`}).join('')}</tbody></table></div><p class="small muted">${x.rev===2?'依据：演示资料 S-01；缺失项没有推测填写。':`本轮提交：${esc(x.updates[x.rev]||'无补充数据')}。${fillMissing(x).length?'未获得本演示支持的完整补充，正文保持原值。':'依据演示补充 S-02 填入；仍须人工核对。'}`}</p></section><button data-tab="full">核对完整 Markdown</button>`}
function fillReceiptView(x,compact=false){const receipt=x.fillReceipts?.[x.rev];if(!receipt)return '';const title=receipt.kind==='applied'?'补充内容已写入 · 待你核对':receipt.kind==='incoming'?'收到新候选 · 尚无意见处理回执':'意见尚未落实 · 需要继续处理';if(compact)return `<div class="receipt-brief"><span>${title}</span><button data-tab="context">查看处理结果</button></div>`;return `<section class="receipt-detail"><h3>本轮意见处理结果</h3><p class="small muted">针对候选 ${receipt.from} 提交 → 返回候选 ${x.rev} · 固定演示回执</p><p><strong>${title}</strong></p>${receipt.text?`<details><summary>查看提交的原始意见</summary><p style="white-space:pre-wrap">${esc(receipt.text)}</p></details>`:''}${receipt.kind==='applied'?`<div class="tablewrap" role="region" tabindex="0" aria-label="意见处理结果"><table><thead><tr><th>你的补充</th><th>返回结果</th></tr></thead><tbody><tr><td>数量：120 件</td><td>已写入数量字段，待核对</td></tr><tr><td>需求日期：2026-09-25</td><td>已写入需求日期字段，待核对</td></tr></tbody></table></div><button data-tab="changes">核对对应文档变化</button><p class="small muted">写入成功不代表内容正确，也不代表你已批准。</p>`:receipt.kind==='incoming'?'<p>这次仅模拟收到一个新版本，没有对应的意见处理结果。不能据此推断上次意见已被执行。</p><button data-tab="changes">核对新旧内容</button>':'<p>当前原型不能解释这段自由输入，因此保留原始意见，未据此修改字段。真实执行结果应说明未处理的内容和原因。</p><button data-quote="本轮意见未落实，请继续处理">继续补充或纠正</button><button data-tab="changes">核对未变的内容</button>'}</section>`}
function fillBody(x){if(state.tab==='changes')return fillReceiptView(x,true)+fillChangesBody(x);if(state.tab==='full')return `<h3>采购申请单 · 填写候选 ${x.rev}</h3><p class="small muted">合成业务记录草稿；未执行客户采购审批。待补充标记保留在字段原位置。</p><button data-action="downloadMd">下载当前 Markdown 候选</button>${templateHtml(fillContent(x))}`;if(state.tab==='sources')return `<h3>填写依据</h3><p>${esc(fillInput)}</p>${fillSnapshot(x).quantity?`<p>演示补充 S-02：${fillReply}</p>`:''}<p class="small muted">S-01 / S-02 均为固定演示资料，不是客户上传的证据。</p><h3>源模板</h3><p>采购申请单 · A/0 · QR-PD-7.4-01</p><a href="templates/application.md" download>下载原始空白 Markdown 模板</a><details><summary>源模板校验信息</summary><p style="overflow-wrap:anywhere">${window.procurementFixtures.application.sourceHash}</p></details>`;return `${fillReceiptView(x)}<h3>填写摘要</h3><p>${fillMissing(x).length?'采购数量和需求日期尚未提供，其他演示业务值已填入。':'采购数量和需求日期已根据演示补充填入，等待检查。'}</p><p>本次演示用途为生产物料；研发样品区保留但不适用。签字空白不由 Agent 代填。</p><p>当前候选由空白表单派生为记录草稿；内部批准不等于客户企业已签批。</p>${inspectionContext(x)}`}
function fillAlert(x){const missing=fillMissing(x);return missing.length?`<div class="scope-alert"><strong>${missing.length} 项信息待补充</strong><p>采购数量、需求日期尚缺。先补充资料，再核对返回版本。</p><button data-quote="采购数量与需求日期">补充这两项</button><button data-action="fillExample">带入演示补充内容</button><small>演示按钮只填入意见框；仍需提交，不会直接改写文档。</small></div>`:''}
function fillAction(a,x){if(x.id!=='application')return false;if(a==='scopeDemo'){toast('请通过补充资料形成新候选');return true}if(a==='fillExample'){if(x.status!=='review'){toast('当前意见正在处理');return true}const draft=x.drafts[x.rev]||'';x.drafts[x.rev]=draft?`${draft}\n${fillReply}`:fillReply;state.reviewPane='feedback';render();$('#feedback').focus();return true}if(a==='downloadMd'){const blob=new Blob([fillContent(x)],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`采购申请单-演示候选-${x.rev}.md`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true}if(a==='returned'||a==='incoming'){if(a==='returned'&&x.status!=='running')return true;if(x.latest>x.rev){toast('已有新候选，请先切换查看');return true}const rev=x.rev+1,snapshot={...fillSnapshot(x)};const text=a==='returned'?x.submitted?.text||'':'';const applied=text.trim()===fillReply||text.trim()===`关于 采购申请单 第 ${x.rev} 轮候选 · 采购数量与需求日期：\n\n${fillReply}`;if(applied){snapshot.quantity='120 件';snapshot.date='2026-09-25'}x.fillReceipts=x.fillReceipts||{};x.fillReceipts[rev]={from:x.rev,text,kind:a==='incoming'?'incoming':applied?'applied':'unhandled'};x.fillVersions=x.fillVersions||{};x.fillVersions[rev]=snapshot;x.latest=rev;x.updates[rev]=text||'模拟收到内容未变的新候选';x.status='review';x.notes.push(`第 ${rev} 版交回（固定演示）；正在查看的第 ${x.rev} 版保持不变。`);render();return true}return false}

window.fillBody=fillBody; window.fillAlert=fillAlert; window.fillAction=fillAction;
